# sampler: (mean difference from the euler render out of 255, brightness, contrast, edge strength). SD 1.5, karras, CFG 7, 20 steps, seed 424242, one prompt.
RENDERS = {'euler': (0.0, 102.4, 72.1, 20.17), 'euler_ancestral': (61.95, 81.6, 51.7, 12.16), 'heun': (22.91, 106.4, 80.5, 23.38), 'dpmpp_2m': (20.92, 105.1, 77.2, 22.93), 'dpmpp_sde': (58.46, 97.0, 72.9, 17.15), 'dpmpp_2m_sde': (66.66, 90.4, 76.3, 23.49), 'dpmpp_3m_sde': (68.1, 86.1, 73.8, 25.98), 'ddim': (0.0, 102.4, 72.1, 20.17), 'lcm': (63.83, 70.1, 54.9, 6.51), 'uni_pc': (28.05, 107.4, 83.5, 20.92), 'res_multistep': (21.27, 105.3, 77.5, 22.86), 'gradient_estimation': (30.17, 109.3, 85.5, 24.65), 'er_sde': (48.34, 92.0, 66.8, 20.81), 'seeds_2': (75.13, 93.1, 87.4, 14.62), 'sa_solver': (45.92, 102.4, 77.9, 15.94)}

det = {k: v for k, v in SOLVERS.items() if v[4]}; sto = {k: v for k, v in SOLVERS.items() if not v[4]}
print(f"bench: {len(SOLVERS)} sampler names, {len(det)} deterministic, {len(sto)} stochastic")
print("calls at 20 steps, grouped: " + "  ".join(f"{c}: {sum(1 for v in SOLVERS.values() if v[0] == c)}" for c in sorted(set(v[0] for v in SOLVERS.values()))))
print("\nsame numbers on the bench as another name (no guidance on the bench)")
print("ddim row equals euler row:", SOLVERS["ddim"] == SOLVERS["euler"], "  euler_cfg_pp equals euler:", SOLVERS["euler_cfg_pp"] == SOLVERS["euler"], "  dpmpp_2m_sde_gpu equals dpmpp_2m_sde:", SOLVERS["dpmpp_2m_sde_gpu"] == SOLVERS["dpmpp_2m_sde"])
assert SOLVERS["ddim"] == SOLVERS["euler"] and RENDERS["ddim"] == RENDERS["euler"]
print("render, ddim against euler: difference", RENDERS["ddim"][0], " every measure equal:", RENDERS["ddim"] == RENDERS["euler"])
print("\ndeterministic samplers at 20 steps, best error first")
print("name           calls  error    slope  error per doubling of calls")
rows = sorted((v[1], k) for k, v in det.items() if k in ("euler", "heun", "dpmpp_2m", "lms", "deis", "uni_pc", "ipndm", "res_multistep", "gradient_estimation", "dpm_2"))
for e, k in rows:
    v = det[k]; print(f"{k:14s} {v[0]:<6d} {e:<8.4f} {v[2]:<6.2f} x{2 ** v[2]:.2f}")
print("\nthe same budget: evaluations at CFG above 1 are calls x 2")
for k in ("euler", "dpmpp_2m", "heun", "dpmpp_sde", "heunpp2"): print(f"{k:10s} 20 steps: {SOLVERS[k][0] * 2} evaluations")
g = lambda names: sum(RENDERS[n][0] for n in names) / len(names)
D = ["heun", "dpmpp_2m", "uni_pc", "res_multistep", "gradient_estimation"]; S = ["euler_ancestral", "dpmpp_sde", "dpmpp_2m_sde", "dpmpp_3m_sde", "er_sde", "seeds_2", "sa_solver"]
print(f"\nrender difference from euler, one seed: deterministic mean {g(D):.1f} (range {min(RENDERS[n][0] for n in D)} to {max(RENDERS[n][0] for n in D)}); noise-adding mean {g(S):.1f} (range {min(RENDERS[n][0] for n in S)} to {max(RENDERS[n][0] for n in S)})")
assert max(RENDERS[n][0] for n in D) < min(RENDERS[n][0] for n in S)
# Does a good bench number predict a picture measure? Rank correlation over the deterministic samplers that have both.
names = [n for n in D + ["euler"]]; rank = lambda xs: [sorted(xs).index(x) for x in xs]
a = rank([SOLVERS[n][1] for n in names]); b = rank([RENDERS[n][3] for n in names]); n_ = len(names); rho = 1 - 6 * sum((x - y) ** 2 for x, y in zip(a, b)) / (n_ * (n_ ** 2 - 1))
print(f"rank correlation, bench error against render edge strength, {n_} samplers, one seed: {rho:+.2f}. Far too few points to mean anything, and that is the point.")
